 try{const raw=await upstream(url,options);return {type:t,...parseWidget(raw.html,t),stale:raw.stale,cached:raw.cached,source_fetched_at:new Date(raw.time).toISOString(),url}}catch(e){console.error('Source feed failure',t,e.message);return {type:t,error:e.message,items:[]}}
