 if(kind==='artist'){
 if(Number(e.format?.id)!==19&&format!=='konser')return false;
 // A name occurring inside a longer name is only a similar result, not an artist match.
 if(needle&&!String(e.name||'').split(/[–—|:]/).some(part=>{const n=eventNameNorm(part);return n===needle||n.startsWith(needle+' ')}))return false;
 }else if(kind==='play'&&!/\btiyatro\b/.test(category))return false;
