const icons={1:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',2:'<path d="M12 3s7 7 7 12a7 7 0 0 1-14 0c0-5 7-12 7-12Z"/>',3:'<path d="M12 3c2 5-3 6-1 10 1-2 4-3 4-5 5 5 4 13-3 13-8 0-9-10-5-13 0 3 1 4 2 4-1-4 3-5 3-9Z"/>',4:'<path d="M3 9a14 14 0 0 1 18 0M6 13a9 9 0 0 1 12 0m-9 4a4 4 0 0 1 6 0"/><circle cx="12" cy="21" r=".5"/>'};
