function updateFilterSummary(){const address=[$('#district').value==='all'?'Mersin geneli':$('#district').selectedOptions[0].textContent,$('#neighborhood').value,$('#street').value].filter(Boolean),category=document.querySelector('.tab[data-type="'+type+'"]'),status=$('#outage-status');const labels=[...address];if(type!=='0')labels.push(category?.childNodes[0].textContent.trim()||'');labels.push(status.selectedOptions[0].textContent);$('#filter-summary').textContent=labels.join(' · ');const count=[$('#district').value!=='all',!!$('#neighborhood').value,!!$('#street').value,type!=='0',status.value!=='all'].filter(Boolean).length;$('#filter-badge').hidden=!count;$('#filter-badge').textContent=count;$('#filter-open').setAttribute('aria-label',count?'Filtrele · '+count+' seçim':'Filtrele');}
$('#filter-open').onclick=()=>$('#filter-dialog').showModal();$('#filter-close').onclick=()=>$('#filter-dialog').close();$('#filter-dialog').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()});
