const addressCache=new Map(),addressSeq={};
async function addressRequest(district,id){const key=district+':'+(id||'');if(!addressCache.has(key)){const r=await fetch('/api/addresses?district='+encodeURIComponent(district)+(id?'&neighborhood='+encodeURIComponent(id):''));if(!r.ok)throw Error('Adresler alınamadı');addressCache.set(key,await r.json())}return addressCache.get(key)}
function setOptions(el,rows,placeholder,wanted=''){el.innerHTML='<option value="">'+escapeHtml(placeholder)+'</option>'+rows.map(r=>'<option value="'+escapeHtml(r.name)+'"'+(r.id?' data-id="'+r.id+'"':'')+'>'+escapeHtml(r.label||r.name)+'</option>').join('');el.disabled=!rows.length;const match=rows.find(r=>placeNorm(r.name)===placeNorm(wanted));if(match)el.value=match.name;else if(wanted){const option=document.createElement('option');option.value=wanted;option.textContent=wanted+' (önceki seçim)';option.selected=true;el.append(option);el.disabled=false}}
async function populateNeighborhoods(prefix,wanted='',street=''){const token=(addressSeq[prefix]||0)+1;addressSeq[prefix]=token;const district=$('#'+prefix+'district').value,n=$('#'+prefix+'neighborhood'),st=$('#'+prefix+'street');setOptions(n,[],'Mahalleler yükleniyor…');setOptions(st,[],'Önce mahalle seç');if(district==='all'){setOptions(n,[],'Önce ilçe seç');return}try{const d=await addressRequest(district);if(addressSeq[prefix]!==token)return;setOptions(n,d.neighborhoods,'Tüm mahalleler',wanted);if(n.value)await populateStreets(prefix,street);if(prefix===''){save();if(data)render()}}catch{if(addressSeq[prefix]===token)setOptions(n,[],'Adresler alınamadı · İlçeyi yeniden seç')}}
async function populateStreets(prefix,wanted=''){const n=$('#'+prefix+'neighborhood'),st=$('#'+prefix+'street'),district=$('#'+prefix+'district').value,option=n.selectedOptions[0],id=option?.dataset.id,selected=n.value;setOptions(st,[],'Sokaklar yükleniyor…');if(!id){setOptions(st,[],'Önce mahalle seç',wanted);return}try{const d=await addressRequest(district,id);if(n.value!==selected||$('#'+prefix+'district').value!==district)return;setOptions(st,d.streets,d.streets.length?'Tüm sokaklar':'Bu mahallede sokak kaydı yok',wanted)}catch{if(n.value===selected)setOptions(st,[],'Sokaklar alınamadı · Tekrar seç')}}
